<?php
require_once __DIR__.'/config.php'; require_admin(); verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=$_POST['action']??'';
 try {
  if($action==='team_save'){
   $id=(int)($_POST['id']??0); $nombre=trim($_POST['nombre_equipo']??''); $disc=trim($_POST['disciplina']??'Fútbol'); $seccion=trim($_POST['seccion']??''); $entrenador=trim($_POST['entrenador']??'');
   if($nombre==='') throw new RuntimeException('Escribe el nombre del equipo.');
   if($id){$s=$conexion->prepare('UPDATE equipo SET nombre_equipo=?,disciplina=?,seccion=?,entrenador=? WHERE id_equipo=?');$s->bind_param('ssssi',$nombre,$disc,$seccion,$entrenador,$id);}else{$s=$conexion->prepare('INSERT INTO equipo(nombre_equipo,disciplina,seccion,entrenador) VALUES(?,?,?,?)');$s->bind_param('ssss',$nombre,$disc,$seccion,$entrenador);} $s->execute(); flash('Equipo guardado correctamente.');
  } elseif($action==='team_delete') { $id=(int)$_POST['id']; $s=$conexion->prepare('DELETE FROM equipo WHERE id_equipo=?');$s->bind_param('i',$id);$s->execute();flash('Equipo eliminado.');
  } elseif($action==='player_save'){
   $id=(int)($_POST['id']??0); $team=(int)($_POST['id_equipo']??0); $nombre=trim($_POST['nombre']??'');$apellido=trim($_POST['apellido']??'');$codigo=trim($_POST['codigo_estudiante']??'');$num=($_POST['numero_camiseta']??'')!==''?(int)$_POST['numero_camiseta']:null;$pos=trim($_POST['posicion']??'');
   if($nombre===''||$apellido==='') throw new RuntimeException('Nombre y apellido son obligatorios.');
   if($id){$s=$conexion->prepare('UPDATE jugador SET id_equipo=NULLIF(?,0),nombre=?,apellido=?,codigo_estudiante=NULLIF(?,\'\'),numero_camiseta=?,posicion=? WHERE id_jugador=?');$s->bind_param('isssisi',$team,$nombre,$apellido,$codigo,$num,$pos,$id);}else{$s=$conexion->prepare('INSERT INTO jugador(id_equipo,nombre,apellido,codigo_estudiante,numero_camiseta,posicion) VALUES(NULLIF(?,0),?,?,NULLIF(?,\'\'),?,?)');$s->bind_param('isssis',$team,$nombre,$apellido,$codigo,$num,$pos);} $s->execute();flash('Jugador registrado correctamente.','success',!$id);
  } elseif($action==='player_delete'){$id=(int)$_POST['id'];$s=$conexion->prepare('DELETE FROM jugador WHERE id_jugador=?');$s->bind_param('i',$id);$s->execute();flash('Jugador eliminado.');
  } elseif($action==='match_save'){
   $id=(int)($_POST['id']??0);$local=(int)($_POST['local']??0);$visitante=(int)($_POST['visitante']??0);$disc=trim($_POST['disciplina']??'Fútbol');$fecha=str_replace('T',' ',$_POST['fecha_partido']??'');$estado=$_POST['estado']??'Programado';$pl=($_POST['puntos_local']??'')!==''?(int)$_POST['puntos_local']:null;$pv=($_POST['puntos_visitante']??'')!==''?(int)$_POST['puntos_visitante']:null;$fair=max(0,min(100,(int)($_POST['fair_play']??100)));
   if(!$local||!$visitante||$local===$visitante||$fecha==='')throw new RuntimeException('Elige dos equipos distintos y una fecha.');
   if(!in_array($estado,['Programado','En curso','Finalizado','Suspendido'],true))throw new RuntimeException('Estado de partido no válido.');
   if($id){$s=$conexion->prepare('UPDATE partido SET id_equipo_local=?,id_equipo_visitante=?,disciplina=?,fecha_partido=?,estado=?,puntos_local=?,puntos_visitante=?,fair_play=? WHERE id_partido=?');$s->bind_param('iisssiiii',$local,$visitante,$disc,$fecha,$estado,$pl,$pv,$fair,$id);}else{$s=$conexion->prepare('INSERT INTO partido(id_equipo_local,id_equipo_visitante,disciplina,fecha_partido,estado,puntos_local,puntos_visitante,fair_play) VALUES(?,?,?,?,?,?,?,?)');$s->bind_param('iisssiii',$local,$visitante,$disc,$fecha,$estado,$pl,$pv,$fair);} $s->execute();flash('Partido registrado correctamente.','success',!$id);
  } elseif($action==='match_delete'){$id=(int)$_POST['id'];$s=$conexion->prepare('DELETE FROM partido WHERE id_partido=?');$s->bind_param('i',$id);$s->execute();flash('Partido eliminado.');}
 } catch(Throwable $e){flash($e instanceof RuntimeException?$e->getMessage():'No se pudo completar la operación. Verifica que los datos no estén duplicados y que el registro no esté vinculado a un partido.','error');}
 header('Location: admin.php#'.(str_contains($action,'team')?'equipos':(str_contains($action,'player')?'jugadores':'partidos')));exit;
}
$teams=$conexion->query('SELECT * FROM equipo ORDER BY nombre_equipo')->fetch_all(MYSQLI_ASSOC);
$players=$conexion->query('SELECT j.*,e.nombre_equipo FROM jugador j LEFT JOIN equipo e ON e.id_equipo=j.id_equipo ORDER BY j.apellido,j.nombre')->fetch_all(MYSQLI_ASSOC);
$matches=$conexion->query('SELECT p.*,l.nombre_equipo local_nombre,v.nombre_equipo visitante_nombre FROM partido p JOIN equipo l ON l.id_equipo=p.id_equipo_local JOIN equipo v ON v.id_equipo=p.id_equipo_visitante ORDER BY p.fecha_partido DESC')->fetch_all(MYSQLI_ASSOC);
$users=(int)$conexion->query("SELECT COUNT(*) c FROM usuarios WHERE estado='Activo'")->fetch_assoc()['c'];$played=(int)$conexion->query("SELECT COUNT(*) c FROM partido WHERE estado='Finalizado'")->fetch_assoc()['c'];$scheduled=(int)$conexion->query("SELECT COUNT(*) c FROM partido WHERE estado IN ('Programado','En curso')")->fetch_assoc()['c'];$avg=(float)$conexion->query('SELECT COALESCE(AVG(fair_play),100) a FROM partido')->fetch_assoc()['a'];
$profilePhoto='';$photoQuery=$conexion->prepare('SELECT foto_perfil FROM perfil_usuario WHERE id_usuario=?');$photoQuery->bind_param('i',$_SESSION['usuario_id']);$photoQuery->execute();$photoRow=$photoQuery->get_result()->fetch_assoc();$profilePhoto=$photoRow['foto_perfil']??'';?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Panel administrador | MokaSports</title><link rel="stylesheet" href="assets/style.css"></head><body class="app-body"><aside class="sidebar"><a class="brand" href="admin.php"><span class="brand-mark">M</span><span>MokaSports</span></a><div class="side-label">GESTIÓN</div><a class="side-link active" href="#resumen">▦ <span>Resumen</span></a><a class="side-link" href="#partidos">◷ <span>Partidos</span></a><a class="side-link" href="#equipos">◈ <span>Equipos</span></a><a class="side-link" href="#jugadores">♙ <span>Jugadores</span></a><div class="sidebar-bottom"><a class="side-link" href="perfil.php">◎ <span>Editar mi perfil</span></a><div class="user-mini"><span class="avatar"><?php if($profilePhoto):?><img src="<?=e($profilePhoto)?>" alt="Foto de perfil"><?php else:?><?=e(mb_substr($_SESSION['nombre']??'A',0,1))?><?php endif;?></span><div><b><?=e($_SESSION['nombre']??'Admin')?></b><small>Administrador</small></div></div><a class="side-link" href="logout.php">↪ <span>Cerrar sesión</span></a></div></aside><main class="main-content"><header class="topbar"><div><span class="eyebrow">PANEL DE CONTROL</span><h1>Dashboard deportivo</h1><p class="muted">Organiza los encuentros y promueve el juego limpio.</p></div><div class="top-actions"><button class="theme-toggle" type="button" aria-label="Cambiar tema">◐ <span>Modo</span></button><a class="btn btn-secondary" href="perfil.php">Editar perfil</a><a class="btn btn-secondary" href="registro.php">Crear cuenta</a><span class="role-chip">● Administrador</span></div></header><?php show_flash(); ?><section id="resumen" class="stats-grid"><article class="stat-card"><span class="stat-icon violet">◈</span><span class="stat-label">Equipos registrados</span><strong><?=$conexion->query('SELECT COUNT(*) c FROM equipo')->fetch_assoc()['c']?></strong><small>Equipos en la plataforma</small></article><article class="stat-card"><span class="stat-icon blue">♙</span><span class="stat-label">Jugadores</span><strong><?=count($players)?></strong><small>Registros de jugadores</small></article><article class="stat-card"><span class="stat-icon orange">◷</span><span class="stat-label">Partidos pendientes</span><strong><?=$scheduled?></strong><small>Programados o en curso</small></article><article class="stat-card"><span class="stat-icon green">✓</span><span class="stat-label">Índice Fair Play</span><strong><?=number_format($avg,0)?> <small>/ 100</small></strong><small>Promedio registrado</small></article></section><section id="partidos" class="content-section"><div class="section-heading"><div><span class="eyebrow">CALENDARIO</span><h2>Partidos</h2><p class="muted">Programa encuentros y actualiza resultados.</p></div></div><form method="post" class="editor-card"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="match_save"><div class="editor-title">＋ Programar o actualizar partido</div><div class="form-grid"><label>Equipo local<select name="local" required><option value="">Seleccionar equipo</option><?php foreach($teams as $t):?><option value="<?=$t['id_equipo']?>"><?=e($t['nombre_equipo'])?></option><?php endforeach;?></select></label><label>Equipo visitante<select name="visitante" required><option value="">Seleccionar equipo</option><?php foreach($teams as $t):?><option value="<?=$t['id_equipo']?>"><?=e($t['nombre_equipo'])?></option><?php endforeach;?></select></label><label>Disciplina<input name="disciplina" value="Fútbol" required></label><label>Fecha y hora<input type="datetime-local" name="fecha_partido" required></label><label>Estado<select name="estado"><option>Programado</option><option>En curso</option><option>Finalizado</option><option>Suspendido</option></select></label><label>Puntos local<input type="number" min="0" name="puntos_local" placeholder="Sin resultado"></label><label>Puntos visitante<input type="number" min="0" name="puntos_visitante" placeholder="Sin resultado"></label><label>Fair Play (0–100)<input type="number" min="0" max="100" name="fair_play" value="100" required></label></div><button class="btn btn-primary" type="submit">Guardar partido</button></form><div class="table-wrap"><table><thead><tr><th>Encuentro</th><th>Fecha</th><th>Estado</th><th>Marcador</th><th>Fair Play</th><th>Acción</th></tr></thead><tbody><?php if(!$matches):?><tr><td colspan="6" class="empty-state">Todavía no hay partidos. Programa el primero arriba.</td></tr><?php endif; foreach($matches as $m):?><tr><td><b><?=e($m['local_nombre'])?></b><div class="muted">vs. <?=e($m['visitante_nombre'])?></div></td><td><?=e(date('d/m/Y H:i',strtotime($m['fecha_partido'])))?></td><td><span class="status status-<?=strtolower(str_replace(' ','-',e($m['estado'])))?>"><?=e($m['estado'])?></span></td><td><b><?=($m['puntos_local']===null?'—':(int)$m['puntos_local'])?> : <?=($m['puntos_visitante']===null?'—':(int)$m['puntos_visitante'])?></b></td><td><?= (int)$m['fair_play'] ?>/100</td><td><form method="post" onsubmit="return confirm('¿Eliminar este partido?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="match_delete"><input type="hidden" name="id" value="<?=$m['id_partido']?>"><button class="btn btn-small btn-danger" type="submit">Eliminar</button></form></td></tr><?php endforeach;?></tbody></table></div></section><section id="equipos" class="content-section"><div class="section-heading"><div><span class="eyebrow">ORGANIZACIÓN</span><h2>Equipos</h2><p class="muted">Administra equipos y disciplinas.</p></div></div><form method="post" class="editor-card"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="team_save"><div class="editor-title">＋ Registrar equipo</div><div class="form-grid"><label>Nombre del equipo<input name="nombre_equipo" required maxlength="100" placeholder="Ej. Cóndores"></label><label>Disciplina<select name="disciplina"><option>Fútbol</option><option>Vóley</option><option>Básquet</option><option>Atletismo</option><option>Otro</option></select></label><label>Sección<input name="seccion" placeholder="Ej. 3° A"></label><label>Entrenador/a<input name="entrenador" placeholder="Nombre del entrenador"></label></div><button class="btn btn-primary" type="submit">Guardar equipo</button></form><div class="table-wrap"><table><thead><tr><th>Equipo</th><th>Disciplina</th><th>Sección</th><th>Entrenador</th><th>Acción</th></tr></thead><tbody><?php if(!$teams):?><tr><td colspan="5" class="empty-state">No hay equipos registrados.</td></tr><?php endif;foreach($teams as $t):?><tr><td><b><?=e($t['nombre_equipo'])?></b></td><td><?=e($t['disciplina'])?></td><td><?=e($t['seccion']?:'—')?></td><td><?=e($t['entrenador']?:'—')?></td><td><form method="post" onsubmit="return confirm('¿Eliminar este equipo? Si tiene partidos asociados, primero deberás gestionar esos partidos.')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="team_delete"><input type="hidden" name="id" value="<?=$t['id_equipo']?>"><button class="btn btn-small btn-danger" type="submit">Eliminar</button></form></td></tr><?php endforeach;?></tbody></table></div></section><section id="jugadores" class="content-section"><div class="section-heading"><div><span class="eyebrow">PLANTILLA</span><h2>Jugadores</h2><p class="muted">Registra deportistas y asígnalos a un equipo.</p></div></div><form method="post" class="editor-card"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="player_save"><div class="editor-title">＋ Registrar jugador</div><div class="form-grid"><label>Nombre<input name="nombre" required maxlength="100"></label><label>Apellido<input name="apellido" required maxlength="100"></label><label>Equipo<select name="id_equipo"><option value="0">Sin equipo asignado</option><?php foreach($teams as $t):?><option value="<?=$t['id_equipo']?>"><?=e($t['nombre_equipo'])?></option><?php endforeach;?></select></label><label>Código de estudiante<input name="codigo_estudiante" maxlength="40" placeholder="Opcional"></label><label>Número de camiseta<input name="numero_camiseta" type="number" min="0" max="255"></label><label>Posición<input name="posicion" placeholder="Ej. Delantero, líbero"></label></div><button class="btn btn-primary" type="submit">Guardar jugador</button></form><div class="table-wrap"><table><thead><tr><th>Jugador</th><th>Equipo</th><th>Código</th><th>Camiseta</th><th>Posición</th><th>Acción</th></tr></thead><tbody><?php if(!$players):?><tr><td colspan="6" class="empty-state">Todavía no hay jugadores registrados.</td></tr><?php endif;foreach($players as $p):?><tr><td><b><?=e($p['nombre'].' '.$p['apellido'])?></b></td><td><?=e($p['nombre_equipo']?:'Sin equipo')?></td><td><?=e($p['codigo_estudiante']?:'—')?></td><td><?=e($p['numero_camiseta']??'—')?></td><td><?=e($p['posicion']?:'—')?></td><td><form method="post" onsubmit="return confirm('¿Eliminar este jugador?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="player_delete"><input type="hidden" name="id" value="<?=$p['id_jugador']?>"><button class="btn btn-small btn-danger" type="submit">Eliminar</button></form></td></tr><?php endforeach;?></tbody></table></div></section><footer class="app-footer">MokaSports <span>·</span> Gestión deportiva con Fair Play</footer></main><script src="assets/app.js"></script></body></html>
